from collections import Counter

def transform(grid):
    """Transform function for task-77262100"""
    g = [r[:] for r in grid]
    H, W = len(g), len(g[0])

    # Find background color
    cnt = Counter(x for r in g for x in r)
    bg = cnt.most_common(1)[0][0]

    # Find 2s line (vertical or horizontal)
    line = None
    vert = None
    for c in range(W):
        if all(g[r][c] == 2 for r in range(H)):
            line, vert = c, True
            break
    for r in range(H):
        if all(g[r][c] == 2 for c in range(W)):
            line, vert = r, False
            break

    # Find special color (not bg, not 2)
    sc = [k for k in cnt if k not in (bg, 2)][0]
    cells = [(r, c) for r in range(H) for c in range(W) if g[r][c] == sc]

    # Clear old special positions
    for r, c in cells:
        g[r][c] = bg

    # Move special cells with appropriate offset
    if vert:
        # Vertical 2s line, determine direction
        if min(c for r, c in cells) > line:
            gap = min(c for r, c in cells) - line - 1
            dr, dc = 0, -gap
        else:
            gap = line - max(c for r, c in cells) - 1
            dr, dc = 0, gap
    else:
        # Horizontal 2s line, determine direction
        if min(r for r, c in cells) > line:
            gap = min(r for r, c in cells) - line - 1
            dr, dc = -gap, 0
        else:
            gap = line - max(r for r, c in cells) - 1
            dr, dc = gap, 0

    # Move cells with offset
    new_cells = [(r + dr, c + dc) for r, c in cells]

    # Place 8s based on 2s-line direction
    if vert:
        # Vertical 2s, place horizontal 8s
        if min(c for r, c in new_cells) > line:
            mc = max(c for r, c in new_cells) + 1
        else:
            mc = min(c for r, c in new_cells) - 1
        for r in range(H):
            g[r][mc] = 8
    else:
        # Horizontal 2s, place vertical 8s
        if max(r for r, c in new_cells) < line:
            mr = max(r for r, c in new_cells) + 1
        else:
            mr = min(r for r, c in new_cells) - 1
        for c in range(W):
            g[mr][c] = 8

    return g

